# GENERATED by targets/codex/build.py from hooks/gates.py. Do not edit; edit the Claude plugin and rebuild.
#!/usr/bin/env python3
"""Approval gates of the GDV AI-KIT (playbook play "Hooks as approval gates").

PreToolUse hook. Active only in a repo whose CLAUDE.md has a "## AI-KIT" section (the plugin may be
installed for repos that do not use the kit), except the bug-fix lock, which is active whenever
.gdv/bugfix-lock.json exists.

Gates:
  review        git push (each pushed branch commit) / gh pr create / glab mr create (HEAD) with no
                .gdv/reviews/<sha>.md; a push whose changes are only under the intent home and .ai/ is exempt
                (written by /ship-review): block (default) or ask, per "review-gate: block|ask|off";
                a recorded review whose verdict is "important" -> ask.
  main-branch   push to main/master/develop, or a push from that branch -> ask
  force-push    git push --force / -f / --force-with-lease / +refspec -> ask
  delete-branch git branch -D, git push --delete, git push origin :branch -> ask
  production    deploy commands aimed at production (defaults below, plus bash_gates) -> ask
  protected     Edit/Write of a protected path (default: migrations, infra, CI files) -> ask
  bugfix-lock   Edit/Write of a test file while .gdv/bugfix-lock.json exists -> ask
  tracker       MCP delete/archive tools, and status changes to Done/Closed/Resolved -> ask

"ask" shows a permission prompt to the person; with no person (claude -p, CI) Claude Code treats it
as a denial. "block" denies with the reason. Project additions: .claude/gdv-gates.json and the file in
GDV_GATES_EXTRA, format {"protected_paths": [glob], "bash_gates": [{"gate", "regex", "reason"}],
"tool_gates": [{"gate", "tool_regex", "reason"}]}; "protected_paths": [] turns the default list off.

No third-party packages. An internal error prints a note to stderr and lets the call through.
"""
import fnmatch, json, os, re, subprocess, sys

DEFAULT_PROTECTED = ["**/migrations/**", "**/migration/**", "infra/**", "terraform/**", "**/*.tf",
                     ".github/workflows/**", ".gitlab-ci.yml", "**/Jenkinsfile", "helm/**", "k8s/**"]
DEFAULT_BASH = [
    {"gate": "production", "regex": r"\b(kubectl|helm|oc)\b[^|;&]*\b(prod|production|prd)\b",
     "reason": "A cluster command aimed at production."},
    {"gate": "production", "regex": r"\bterraform\s+(apply|destroy)\b",
     "reason": "terraform apply/destroy changes real infrastructure."},
    {"gate": "production", "regex": r"\b(deploy|release|rollout)\b[^|;&]*\b(prod|production|prd)\b",
     "reason": "A deploy or release to production."},
    {"gate": "production", "regex": r"\bvercel\b[^|;&]*--prod\b|\bnetlify\s+deploy\b[^|;&]*--prod\b",
     "reason": "A production deploy."},
]
TEST_RE = r"(^|/)(tests?|__tests__|spec|specs|e2e)/|(^|/)test_[^/]*$|_test\.[A-Za-z0-9]+$|\.(test|spec)\.[A-Za-z0-9]+$"
MAIN = r"(main|master|develop|trunk)"
EDIT_TOOLS = ("Edit", "Write", "MultiEdit", "NotebookEdit")


def ai_kit(cwd):
    """The AI-KIT section of <cwd>/CLAUDE.md as a dict, or None when the repo does not use the kit."""
    root = git(cwd, "rev-parse", "--show-toplevel") or cwd
    for base in (cwd, root):
        try:
            text = open(os.path.join(base, "CLAUDE.md"), encoding="utf-8").read()
        except OSError:
            continue
        m = re.search(r"^## AI-KIT\s*$(.*?)(?=^## |\Z)", text, re.S | re.M)
        if m:
            return dict(re.findall(r"^-\s*([a-z-]+):\s*(\S[^#\n]*?)\s*(?:#.*)?$", m.group(1), re.M))
    return None


def git(cwd, *args):
    try:
        r = subprocess.run(["git", "-C", cwd, *args], capture_output=True, text=True, timeout=5)
        return r.stdout.strip() if r.returncode == 0 else ""
    except Exception:  # noqa: BLE001
        return ""


def extra_config(root):
    cfg = {"protected_paths": None, "bash_gates": [], "tool_gates": []}
    for f in (os.path.join(root, ".claude", "gdv-gates.json"), os.environ.get("GDV_GATES_EXTRA") or ""):
        if not f or not os.path.isfile(f):
            continue
        try:
            d = json.load(open(f, encoding="utf-8"))
        except Exception as e:  # noqa: BLE001
            print(f"gates: cannot read {f}: {e}", file=sys.stderr)
            continue
        if "protected_paths" in d:
            cfg["protected_paths"] = (cfg["protected_paths"] or []) + list(d["protected_paths"])
        cfg["bash_gates"] += d.get("bash_gates", [])
        cfg["tool_gates"] += d.get("tool_gates", [])
    return cfg


def out(decision, gate, reason):
    tail = " Ask the person to approve it or do it themselves; do not look for another way around." \
        if decision == "ask" else ""
    print(json.dumps({"hookSpecificOutput": {
        "hookEventName": "PreToolUse",
        "permissionDecision": "deny" if decision == "block" else "ask",
        "permissionDecisionReason": f"[gate: {gate}] {reason}{tail}"}}))
    return True


def rel(path, cwd, root):
    """Path relative to the repo root, with / separators (the session may run in a subfolder)."""
    return os.path.relpath(os.path.realpath(os.path.join(cwd, path)), os.path.realpath(root)).replace(os.sep, "/")


def lock_check(tin, cwd, root):
    path = tin.get("file_path") or tin.get("notebook_path")
    lock_file = os.path.join(root, ".gdv", "bugfix-lock.json")
    if not path or not os.path.isfile(lock_file):
        return False
    try:
        lock = json.load(open(lock_file, encoding="utf-8"))
    except Exception as e:  # noqa: BLE001
        print(f"gates: cannot read {lock_file}: {e}", file=sys.stderr)
        return False
    r = rel(path, cwd, root)
    if r == ".gdv/bugfix-lock.json":
        return False
    if r in (lock.get("test_files") or []) or re.search(lock.get("test_regex") or TEST_RE, r):
        return out("ask", "bugfix-lock",
                   f"Fixing bug {lock.get('item', '?')}: test files are locked, the fix must not change the tests. "
                   f"{r} is a test file. If the test itself is wrong, stop and tell the person.")
    return False


def protected_check(tin, cwd, root, cfg):
    path = tin.get("file_path") or tin.get("notebook_path")
    if not path:
        return False
    r = rel(path, cwd, root)
    globs = DEFAULT_PROTECTED if cfg["protected_paths"] is None else cfg["protected_paths"]
    for g in globs:
        if fnmatch.fnmatch(r, g) or (g.startswith("**/") and fnmatch.fnmatch(r, g[3:])):
            return out("ask", "protected", f"{r} is a protected path ({g}): migrations, infrastructure and CI "
                                           "changes need a person's approval.")
    return False


VALUE_OPTS = ("-o", "--push-option", "--repo", "--receive-pack", "--exec")


def push_args(cmd):
    """The arguments after `git push`, without option values (-o ci.skip), or None when cmd is no push."""
    m = re.search(r"\bgit\b[^|;&]*?\bpush\b([^|;&]*)", cmd)
    if not m:
        return None
    out_, skip = [], False
    for a in m.group(1).split():
        if skip:
            skip = False
            continue
        if a in VALUE_OPTS:
            skip = True
            continue
        out_.append(a)
    return out_


def push_checks(cmd, cwd, kit):
    args = push_args(cmd)
    is_pr = re.search(r"\b(gh\s+pr\s+create|glab\s+mr\s+create)\b", cmd)
    if args is None and not is_pr:
        return False
    if args is not None:
        pos = [a for a in args if not a.startswith("-")]
        if any(re.fullmatch(r"--force(-with-lease)?(=.*)?|-f", a) for a in args) or any(a.startswith("+") for a in pos[1:]):
            return out("ask", "force-push", "A force push rewrites shared history.")
        if "--delete" in args or "-d" in args or any(a.startswith(":") for a in pos[1:]):
            return out("ask", "delete-branch", "This push deletes a remote branch.")
        if any(re.fullmatch(rf"\+?(\S+:)?(refs/heads/)?{MAIN}", a) for a in pos[1:]):
            return out("ask", "main-branch", "Pushing to the main branch skips the PR/MR and its review.")
        if re.fullmatch(MAIN, git(cwd, "rev-parse", "--abbrev-ref", "HEAD") or "-"):
            return out("ask", "main-branch", "The current branch is the main branch: work on a change branch.")
    mode = (kit.get("review-gate") or "block").strip().lower()
    if mode == "off":
        return False
    root = git(cwd, "rev-parse", "--show-toplevel") or cwd
    for name, sha in pushed_commits(args, cwd) if args is not None else [("HEAD", git(cwd, "rev-parse", "HEAD"))]:
        if not sha or docs_only(cwd, sha, kit):
            continue
        review = review_for(cwd, root, sha, kit)
        if not review:
            return out("ask" if mode == "ask" else "block", "review",
                       f"{name} ({sha[:8]}) has no AI review. Run /ship-review on it first (it records "
                       f".gdv/reviews/{sha[:8]}...md), then push again. Code committed after a review needs a new "
                       "review; intent and .ai/ files committed after it do not.")
        try:
            verdict = re.search(r"^Verdict:\s*(\S+)", open(review, encoding="utf-8").read(), re.M | re.I)
        except OSError:
            verdict = None
        if verdict and verdict.group(1).lower().startswith("important"):
            return out("ask", "review", f"The review of {name} ({sha[:8]}) has Important findings. The Dev lead "
                                        "decides whether this push goes ahead.")
    return False


def doc_prefixes(kit):
    home = (kit.get("intent-home") or "./intent").strip()
    prefixes = [".ai/"]
    if not home.startswith(".."):
        prefixes.append(os.path.normpath(home).replace(os.sep, "/").rstrip("/") + "/")
    return prefixes


def only_docs(cwd, base, sha, kit):
    """True when base..sha changes at least one file and every changed file is under the intent home or .ai/."""
    files = [f for f in git(cwd, "diff", "--name-only", base, sha).splitlines() if f]
    pre = doc_prefixes(kit)
    return bool(files) and all(any(f.startswith(p) for p in pre) for f in files)


def review_for(cwd, root, sha, kit):
    """The review file of sha, or of its nearest reviewed ancestor when only documents (intent home, .ai/:
    status, links.md, work-log records) were committed since that review. None when there is none."""
    def path(c):
        f = os.path.join(root, ".gdv", "reviews", c + ".md")
        return f if os.path.isfile(f) else None
    if path(sha):
        return path(sha)
    for anc in git(cwd, "rev-list", "--first-parent", "--max-count=50", sha).splitlines()[1:]:
        if path(anc):
            return path(anc) if only_docs(cwd, anc, sha, kit) else None
    return None


def docs_only(cwd, sha, kit):
    """True when every change sha brings over the main branch is under the intent home or .ai/ (documents:
    BA and QC commits need no AI code review)."""
    base = ""
    for ref in ("origin/HEAD", "origin/main", "origin/master", "main", "master"):
        if git(cwd, "rev-parse", "--verify", "--quiet", ref):
            base = git(cwd, "merge-base", ref, sha)
            break
    if not base or base == sha:
        return False
    return only_docs(cwd, base, sha, kit)


def is_tag(cwd, name):
    try:
        return subprocess.run(["git", "-C", cwd, "show-ref", "--verify", "--quiet", f"refs/tags/{name}"],
                              capture_output=True, timeout=5).returncode == 0
    except Exception:  # noqa: BLE001
        return False


def pushed_commits(args, cwd):
    """(name, commit sha) for each branch a git push sends. No refspec -> HEAD (also with --follow-tags).
    --tags alone pushes only tags. Tags are not reviewed."""
    pos = [a for a in args if not a.startswith("-")]
    specs = pos[1:]
    if not specs:
        return [] if "--tags" in args else [("HEAD", git(cwd, "rev-parse", "HEAD"))]
    res = []
    for spec in specs:
        src = spec.lstrip("+").split(":", 1)[0]
        if not src or src.startswith("refs/tags/") or is_tag(cwd, src):
            continue
        res.append((src, git(cwd, "rev-parse", "--verify", "--quiet", f"{src}^{{commit}}")))
    return res


def bash_checks(cmd, cwd, kit, cfg):
    if push_checks(cmd, cwd, kit):
        return True
    if re.search(r"\bgit\s+branch\s+(-D|--delete\s+--force|-d)\b", cmd):
        return out("ask", "delete-branch", "Deleting a branch can lose unreviewed work.")
    for g in DEFAULT_BASH + cfg["bash_gates"]:
        if re.search(g["regex"], cmd, re.I):
            return out("ask", g.get("gate", "custom"), g.get("reason", "A gated command."))
    return False


DONE = r"^\s*(done|closed?|resolved|complete[d]?)\s*$"


def tool_checks(tool, tin, cfg):
    bare = tool.split("__")[-1]
    for g in cfg["tool_gates"]:
        if re.search(g["tool_regex"], tool, re.I):
            return out("ask", g.get("gate", "custom"), g.get("reason", "A gated tool."))
    if re.search(r"(^|_)(delete|archive|remove|destroy)|^delete|Delete|Archive", bare):
        return out("ask", "tracker-delete", f"{bare} deletes or archives data. A person does it.")
    if re.search(r"transition|update_item|updateJiraIssue|editJiraIssue", bare, re.I):
        for k in ("to_status_name", "status", "status_name", "transition", "transitionName"):
            v = tin.get(k)
            if isinstance(v, dict):
                v = v.get("name") or v.get("id")
            if v is not None and re.search(DONE, str(v), re.I):
                return out("ask", "tracker-done", "Closing a ticket (Done) is a person's acceptance.")
        if re.search(r"transitionJiraIssue", bare) or "to_status_id" in tin or "status_id" in tin:
            return out("ask", "tracker-done", "A status change passed by id cannot be checked; a person confirms it.")
    return False


def pre(data):
    tool, tin = data.get("tool_name", ""), data.get("tool_input") or {}
    cwd = data.get("cwd") or os.getcwd()
    root = git(cwd, "rev-parse", "--show-toplevel") or cwd
    if tool in EDIT_TOOLS and lock_check(tin, cwd, root):
        return
    kit = ai_kit(cwd)
    if kit is None:
        return
    cfg = extra_config(root)
    if tool in EDIT_TOOLS:
        protected_check(tin, cwd, root, cfg)
    elif tool == "Bash":
        bash_checks(str(tin.get("command", "")), cwd, kit, cfg)
    elif tool.startswith("mcp__"):
        tool_checks(tool, tin, cfg)


def main():
    try:
        data = json.load(sys.stdin)
    except Exception:  # noqa: BLE001
        return 0
    try:
        pre(data)
    except Exception as e:  # noqa: BLE001
        print(f"gates: {e}", file=sys.stderr)
    return 0


if __name__ == "__main__":
    sys.exit(main())
